{
  "name": "gqa",
  "op_type": "causal_grouped_query_attention_prefill",
  "axes": {
    "B": {
      "type": "const",
      "value": 1
    },
    "S": {
      "type": "const",
      "value": 16384
    },
    "HQ": {
      "type": "const",
      "value": 32
    },
    "HKV": {
      "type": "const",
      "value": 8
    },
    "D": {
      "type": "const",
      "value": 128
    }
  },
  "inputs": {
    "q": {
      "shape": [
        "B",
        "S",
        "HQ",
        "D"
      ],
      "dtype": "bfloat16",
      "description": "Contiguous BSHD; element strides [67108864, 4096, 128, 1]."
    },
    "k": {
      "shape": [
        "B",
        "S",
        "HKV",
        "D"
      ],
      "dtype": "bfloat16",
      "description": "Contiguous BSHD; element strides [16777216, 1024, 128, 1]."
    },
    "v": {
      "shape": [
        "B",
        "S",
        "HKV",
        "D"
      ],
      "dtype": "bfloat16",
      "description": "Contiguous BSHD; element strides [16777216, 1024, 128, 1]."
    }
  },
  "outputs": {
    "o": {
      "shape": [
        "B",
        "S",
        "HQ",
        "D"
      ],
      "dtype": "bfloat16",
      "description": "Contiguous BSHD; element strides [67108864, 4096, 128, 1]."
    }
  },
  "reference": "import math\n\nimport torch\n\nREFERENCE_ROWS = 256\n\n\n@torch.inference_mode()\ndef run(q, k, v):\n    batch, sequence, q_heads, head_dim = q.shape\n    kv_heads = k.shape[2]\n    assert q_heads % kv_heads == 0\n    assert k.shape == v.shape == (batch, sequence, kv_heads, head_dim)\n    assert q.dtype == k.dtype == v.dtype == torch.bfloat16\n\n    # Expand head indices explicitly; row chunks bound reference memory.\n    groups = torch.arange(q_heads, device=q.device) // (q_heads // kv_heads)\n    queries = q.transpose(1, 2).float()\n    keys = k.transpose(1, 2).float().index_select(1, groups)\n    values = v.transpose(1, 2).float().index_select(1, groups)\n    output = torch.empty_like(q)\n    key_positions = torch.arange(sequence, device=q.device)\n    scale = 1.0 / math.sqrt(head_dim)\n\n    # The oracle uses full FP32 products, softmax, and value accumulation.\n    previous_tf32 = torch.backends.cuda.matmul.allow_tf32\n    torch.backends.cuda.matmul.allow_tf32 = False\n    try:\n        for start in range(0, sequence, REFERENCE_ROWS):\n            stop = min(start + REFERENCE_ROWS, sequence)\n            scores = torch.matmul(queries[:, :, start:stop], keys.transpose(-1, -2))\n            scores.mul_(scale)\n            query_positions = torch.arange(start, stop, device=q.device)\n            scores.masked_fill_(key_positions[None, :] > query_positions[:, None], -torch.inf)\n            weights = torch.softmax(scores, dim=-1)\n            result = torch.matmul(weights, values)\n            output[:, start:stop] = result.transpose(1, 2).to(q.dtype)\n    finally:\n        torch.backends.cuda.matmul.allow_tf32 = previous_tf32\n\n    return output\n"
}

