    int64_t n2Offset = 0;
    int64_t gOffset = 0;
    if constexpr (layOutType == LayOutTypeEnum::LAYOUT_SBH) {
        s1Offset = extraInfo.s1oIdx * this->s1BaseBN2GDRope;
        bOffset = extraInfo.boIdx * this->n2GDRope;
