__global__ __aicore__ void qkSm(GM_ADDR q, GM_ADDR k, GM_ADDR scores, GM_ADDR probs,
                                int row, int n, int srow, int sn) {
    KERNEL_TASK_TYPE_DEFAULT(KERNEL_TYPE_MIX_AIC_1_2);
    if ASCEND_IS_AIC {
        if (row < S) {
            TPipe pipe;
            auto tiling = Tiling(n, D);
            Matmul<A, BTrans, CS, C> mm;
            mm.Init(&tiling, &pipe);
            GlobalTensor<BF> qg, kg;
            GlobalTensor<half> sg;
            qg.SetGlobalBuffer((__gm__ BF*)q); kg.SetGlobalBuffer((__gm__ BF*)k);
            sg.SetGlobalBuffer((__gm__ half*)scores);
            for (int h = GetBlockIdx(); h < HQ; h += GetBlockNum()) {
                mm.SetTensorA(qg[(h*S+row)*D]); mm.SetTensorB(kg[(h/(HQ/HK))*S*D], true);
                mm.IterateAll(sg[h*M*n]); mm.End();
            }
